 return {x:-b.x,z:b.z,active,warning:b.phase==='warning',yaw:Math.hypot(dx,dz)>.00001?Math.atan2(-dx,dz):null,height:b.phase==='chase'&&e?Math.sin(clamp(e.elapsed/1.15,0,1)*Math.PI)*4:0,kick,walk:b.phase==='patrol'?Math.sin(g.time*13)*.5:0};
