 set(p){if('sideways'in p)this.sideways=Boolean(p.sideways);if('limit'in p)this.limit=normalizeLimit(p.limit);if('orientation'in p)this.orientation=normalizeOrientation(p.orientation);try{this.storage?.setItem('overtime-pinball-round-options-v1',JSON.stringify({limit:this.limit,orientation:this.orientation,sideways:this.sideways}));}catch{}}
 best(limit=this.limit){const key=this.key(limit);let best=this.records.get(key)||0;try{if(!this.storage)throw Error('storage unavailable');const value=Number(this.storage.getItem(key));if(Number.isFinite(value)&&value>0)best=Math.max(best,value);}catch{this.unsaved.add(key);}this.records.set(key,best);return best;}
 sessionOnly(limit=this.limit){return !this.storage||this.unsaved.has(this.key(limit));}
 key(limit){return normalizeLimit(limit)?'overtime-pinball-best-timed-'+normalizeLimit(limit)+'-v1':'overtime-pinball-best-v5';}
 record(score,limit=this.limit){const key=this.key(limit),before=this.best(limit),best=Number.isFinite(score)?Math.max(before,Math.floor(score)):before;this.records.set(key,best);try{if(!this.storage)throw Error('storage unavailable');this.storage.setItem(key,String(best));this.unsaved.delete(key);}catch{this.unsaved.add(key);}return best;}
}

import {sweepCircle} from './contact.js';
const HOME={x:0,z:-16},clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export const bossPath=side=>[HOME,{x:0,z:-19},{x:13*side,z:-19},{x:13*side,z:-7},{x:16*side,z:-4},{x:16*side,z:14.7},{x:-16*side,z:14.7},{x:-16*side,z:-4},{x:-13*side,z:-7},{x:-13*side,z:-19},{x:0,z:-19},HOME];
export const normalizeLimit=n=>[60,180].includes(Number(n))?Number(n):0;
export const freshRound=limit=>({limit:normalizeLimit(limit),remaining:normalizeLimit(limit)||null,warning:false,ending:null,reason:null,reentry:null,reentries:0});
export const freshBoss=()=>({phase:'home',x:HOME.x,z:HOME.z,previousX:HOME.x,previousZ:HOME.z,elapsed:0,nextAt:18,kickReady:0,kickUntil:0,cycle:0,path:[],leg:0});
export function startReentry(g){
 const r=g.round;if(!r.limit||r.remaining<=0||r.ending||r.reentry)return false;
 r.reentries++;const side=g.ball.x===0?(r.reentries%2?1:-1):Math.sign(g.ball.x);
 r.reentry={elapsed:0,duration:1.5,from:{x:g.ball.x,z:g.ball.z},side};
 g.combo=0;g.lastHit=-99;g.comboRoutes.active=null;g.mailRun=null;g.interaction=null;g.opportunity=null;g.arming=null;g.cancelInput();
 g.central.available=false;g.central.litBefore=false;g.flippers={left:0,right:0};g.flipperStroke={left:0,right:0};g.flipperPulse={left:0,right:0};g.chairBoost.remaining=0;g.effect=null;g.hop=0;g.ball.vx=g.ball.vz=0;
 g.emit('reentryStart',{count:r.reentries});return true;
}
export function updateReentry(g,dt){
 const r=g.round.reentry;if(!r)return;
 r.elapsed=Math.min(r.duration,r.elapsed+dt);const t=r.elapsed/r.duration,u=t*t*(3-2*t);
 // Return around the outside to the clear upper-office aisle, away from the exit.
 // A controlled side launch avoids a direct copier hit; no new invulnerability,
 // collision, lamp or reward checks are introduced during the return animation.
 g.ball.x=r.from.x*(1-u)+r.side*14*Math.sin(Math.PI*u);g.ball.z=r.from.z+(-11.3-r.from.z)*u;g.hop=Math.sin(Math.PI*t)*.8;
 g.tapQueue.length=0;g.pendingTap=null;
 if(r.elapsed>=r.duration-1e-8){Object.assign(g.ball,{x:0,z:-11.3,vx:r.side*10,vz:12});g.round.reentry=null;g.hop=.3;g.cancelInput();g.interactionReady=Math.max(g.interactionReady,g.time+.6);g.bossPatrol.kickReady=Math.max(g.bossPatrol.kickReady,g.time+.6);g.emit('reentryEnd');}
}
export function startTimedEnding(g){
 const r=g.round;if(r.ending)return;r.remaining=0;r.reason='time';
 r.reentry=null;
 r.ending={elapsed:0,from:{x:g.ball.x,z:g.ball.z},bossFrom:{x:g.bossPatrol.x,z:g.bossPatrol.z},kicked:false};
 g.mailRun=null;g.interaction=null;g.opportunity=null;g.arming=null;g.cancelInput();g.flipperStroke={left:0,right:0};g.flipperPulse={left:0,right:0};g.ball.vx=g.ball.vz=0;
 g.bossPatrol.phase='chase';g.emit('timeUp');
}
// Called only while Game is playing, after the work-scene early return.
export function updateRound(g,dt){
 const r=g.round;
 if(r.ending){const e=r.ending;e.elapsed+=dt;const t=clamp(e.elapsed/1.15,0,1),ease=t*t*(3-2*t),b=g.bossPatrol;
  b.x=e.bossFrom.x+(e.from.x-e.bossFrom.x)*ease;b.z=e.bossFrom.z+(e.from.z-1.9-e.bossFrom.z)*ease;
  if(e.elapsed>=1.15&&!e.kicked){e.kicked=true;b.phase='kick';g.emit('forcedKick');}
  if(e.kicked){const q=clamp((e.elapsed-1.15)/.85,0,1),u=q*q*(3-2*q);g.ball.x=e.from.x*(1-u);g.ball.z=e.from.z+(52-e.from.z)*u;g.hop=Math.sin(q*Math.PI)*1.5;}
  if(e.elapsed>=2){g.state='over';g.hop=0;g.emit('over',{reason:'time'});}return true;
 }
 if(r.remaining===null)return false;
 const before=r.remaining;r.remaining=Math.max(0,before-dt);
 if(!r.warning&&r.remaining<=5){r.warning=true;g.emit('timeWarning');}
 if(r.remaining<=1e-8){if(!r.reentry)g.time+=before;startTimedEnding(g);return true;}return false;
}
export function updateBoss(g,dt){
 const b=g.bossPatrol;b.previousX=b.x;b.previousZ=b.z;if(!g.patrolEnabled)return;
 if(b.phase==='home'&&g.time>=b.nextAt){b.phase='warning';b.elapsed=0;g.emit('bossWarning');}
 if(b.phase==='warning'){b.elapsed+=dt;if(b.elapsed<2)return;const side=b.cycle%2?1:-1;b.phase='patrol';b.path=bossPath(side);b.leg=1;g.emit('bossPatrol');}
 if(b.phase!=='patrol')return;
 let travel=dt*15;
 while(travel>0&&b.leg<b.path.length){const p=b.path[b.leg],dx=p.x-b.x,dz=p.z-b.z,d=Math.hypot(dx,dz);if(d<=travel){b.x=p.x;b.z=p.z;travel-=d;b.leg++;}else{b.x+=dx/d*travel;b.z+=dz/d*travel;travel=0;}}
 if(b.leg===b.path.length){b.phase='home';b.cycle++;const sample=g.random?.(),r=Number.isFinite(sample)?clamp(sample,0,1):(b.cycle*.61803398875)%1;b.nextAt=g.time+18+12*r;g.emit('bossHome');}
}
export function patrolContact(g,from,to){
 const b=g.bossPatrol;if(b.phase!=='patrol'||g.time<b.kickReady)return null;
 const h=sweepCircle({x:from.x-b.previousX,z:from.z-b.previousZ},{x:to.x-b.x,z:to.z-b.z},{x:0,z:0,r:1.3},g.ball.r);
 if(!h)return null;return {...h,x:h.x+b.previousX+(b.x-b.previousX)*h.t,z:h.z+b.previousZ+(b.z-b.previousZ)*h.t,station:{id:'patrol-boss',type:'boss',patrol:true}};
}
export function kickByPatrol(g){
 const b=g.ball,p=g.bossPatrol,dx=clamp(-b.x*.35,-6,6),dz=22;
 b.vx=dx;b.vz=dz;g.hop=.8;p.kickReady=g.time+2;p.kickUntil=g.time+.45;g.interactionReady=Math.max(g.interactionReady,g.time+.45);g.emit('bossKick');
}

// Final-round snapshots only. These adapters never read historical local bests.
export const BOARD_METRICS=Object.freeze({
 'overtime-pinball-60s':{rules:'office-v0826-reentry-60-v1',unit:'points',status:'done',direction:'desc'},
 'overtime-pinball-180s':{rules:'office-v0826-reentry-180-v1',unit:'points',status:'done',direction:'desc'},
 'overtime-pinball-unlimited':{rules:'office-v0826-drain-unlimited-v1',unit:'points',status:'done',direction:'desc'},
 'courtesy-contest':{rules:'press-courtesy-v2',unit:'courtesies',status:'seated',direction:'desc',secondary:true,secondaryUnit:'秒'},
 'long-jump':{rules:'journey-km-v1',unit:'km',status:'valid',direction:'desc'},
 hurdles:{rules:'110m-8h-v1',unit:'s',status:'done',direction:'asc'},
 'high-jump':{rules:'cleared-height-v1',unit:'m',status:'cleared',direction:'desc'},
 'pole-vault':{rules:'real-altitude-v3',unit:'m',status:'done',direction:'desc'},
 'shot-put':{rules:'relay-distance-v1',unit:'m',status:'valid',direction:'desc'},
 discus:{rules:'wind-ufo-distance-v1',unit:'m',status:'valid',direction:'desc'},
 'reaction-rod':{rules:'catch-rating-v1',unit:'catches',status:'done',direction:'desc',secondary:true},
 'beer-slide':{rules:'accuracy-retention-v1',unit:'points',status:'valid',direction:'desc'},
 'run-400m':{rules:'400m-prototype-v3',unit:'s',status:'done',direction:'asc'},
 'run-1500m':{rules:'1500m-rival-tiers-v5',unit:'s',status:'done',direction:'asc'},
 'tower-climb':{rules:'indoor-10floors-v1',unit:'s',status:'summit',direction:'asc'}
});
export function resultToSubmission(game,r){
 const b=Object.hasOwn(BOARD_METRICS,game)?BOARD_METRICS[game]:null;
 if(!b||!r||r.phase!=='done')return null;
 if(game.startsWith('overtime-pinball-')){
  const limit={'overtime-pinball-60s':60,'overtime-pinball-180s':180,'overtime-pinball-unlimited':0}[game];
  if(r.game!==game||r.limit!==limit||r.reason!==(limit===0?'drain':'time')||!Number.isSafeInteger(r.score)||r.score<0||r.score>=Number.MAX_SAFE_INTEGER)return null;
  return {score:r.score,status:b.status};
 }
 let score;
 if(game==='courtesy-contest'){
  if(r.seated!==true||!Number.isSafeInteger(r.count)||r.count<0||r.count>=Number.MAX_SAFE_INTEGER||typeof r.remaining!=='number'||!Number.isFinite(r.remaining)||r.remaining<.01||r.remaining>30||Math.abs(r.remaining*100-Math.round(r.remaining*100))>1e-9)return null;
  return {score:r.count,status:b.status,secondaryScore:r.remaining};
 }
 switch(game){
 case 'long-jump':if(r.valid!==true)return null;score=r.legalAdventureKm;break;
 case 'hurdles':score=r.t;if(score>180)return null;break;
 case 'high-jump':if(r.success!==true)return null;score=r.height;break;
 case 'pole-vault':if(r.ruleset!==b.rules||r.scoreSnapshot?.ruleset!==b.rules)return null;score=r.scoreSnapshot.height;break;
 case 'shot-put':if(r.valid!==true)return null;score=r.distance;break;
 case 'discus':if(r.foul!==false)return null;score=r.score;break;
 case 'reaction-rod':score=r.caught;if(!Number.isInteger(score)||score>10||!Number.isFinite(r.rating)||r.rating<0||r.rating>10)return null;break;
 case 'beer-slide':if(r.fallen||r.invalid||r.invalidReason||r.cancelled)return null;score=r.raw;if(score>10)return null;break;
 case 'run-400m':case 'run-1500m':if(r.finished!==true||r.ruleset!==b.rules||r.scoreSnapshot?.ruleset!==b.rules)return null;score=r.scoreSnapshot.seconds;break;
 case 'tower-climb':if(r.finished!==true||r.floor!==10)return null;score=r.time;if(score>60)return null;break;
 }
 if(game==='run-400m'&&(score<30||score>=3600))return null;
 if(typeof score!=='number'||!Number.isFinite(score)||score<=0)return null;
 return {score,status:b.status,...(b.secondary?{secondaryScore:r.rating}:{})};
}

// Exact additive boundary for the approved PreviewFastGate import. Live behavior tests
// continue reading node:fs and runtime modules, never this historical view.
import {readFileSync as actual} from 'node:fs';
import {createHash} from 'node:crypto';
import {fileURLToPath} from 'node:url';
import {resolve,relative,sep,isAbsolute} from 'node:path';
import assert from 'node:assert/strict';
const root=fileURLToPath(new URL('../../',import.meta.url));
export const sha256=b=>createHash('sha256').update(b).digest('hex');
export const gitBlob=b=>createHash('sha1').update(`blob ${b.length}\0`).update(b).digest('hex');
const baselineBytes=actual(new URL('../../docs/preview-fast-gate/BASELINE.json',import.meta.url));
assert.equal(sha256(baselineBytes),'dba8697154851aca8e9be4b8bfb3aaa12da7638208cb3fafeb8299ba254b8a88','immutable PreviewFastGate parent and admitted paths');
const freeze=value=>{if(value&&typeof value==='object'){Object.values(value).forEach(freeze);Object.freeze(value);}return value;};
export const baseline=freeze(JSON.parse(baselineBytes));
const previous=new Map(baseline.files.map(f=>[f.path,f.gitBlob]));
export function verifyBase(b){
 assert.equal(b.baseCommit,'a5ee5ccc8eb7e8db7a866e461dec969272802f8a');assert.equal(b.baseTree,'39f3e0cdf95d11e8dbf0e39763ed607b6b086f44');assert.deepEqual(b,baseline);
 const tree={};for(const f of b.files){const parts=f.path.split('/');let d=tree;for(const name of parts.slice(0,-1))d=d[name]??={};assert.ok(!d[parts.at(-1)],'duplicate parent path');d[parts.at(-1)]={file:f};}
 function digest(d){const entries=Object.entries(d).sort(([a,x],[b,y])=>Buffer.compare(Buffer.from(a+(x.file?'':'/')),Buffer.from(b+(y.file?'':'/'))));const bytes=Buffer.concat(entries.map(([n,x])=>Buffer.concat([Buffer.from(`${x.file?x.file.mode:'40000'} ${n}\0`),Buffer.from(x.file?x.file.gitBlob:digest(x),'hex')])));return createHash('sha1').update(`tree ${bytes.length}\0`).update(bytes).digest('hex');}
 assert.equal(digest(tree),b.baseTree);return true;
}
verifyBase(baseline);
const manifestPath='docs/preview-fast-gate/MANIFEST.json';
let cachedText,cached;const validated=new WeakSet();
export function manifest(){const text=actual(new URL('../../'+manifestPath,import.meta.url),'utf8');if(text!==cachedText){const parsed=freeze(JSON.parse(text));cachedText=text;cached=parsed;}return cached;}
export function validate(m){
 if(m===cached&&validated.has(m))return m;
 assert.equal(m.baseCommit,baseline.baseCommit);assert.equal(m.baseTree,baseline.baseTree);
 assert.deepEqual(m.files.map(f=>f.path).sort(),baseline.modifiedPaths);
 assert.deepEqual([...m.addedPaths].sort(),baseline.addedPaths);
 assert.deepEqual(m.addedFiles.map(f=>f.path).sort(),baseline.addedPaths.filter(p=>p!==manifestPath));
 for(const f of m.files){assert.equal(typeof f.beforeText,'string');const b=Buffer.from(f.beforeText);assert.equal(f.beforeGitBlob,previous.get(f.path));assert.equal(gitBlob(b),f.beforeGitBlob);assert.equal(sha256(b),f.beforeSha256);assert.match(f.gitBlob,/^[a-f0-9]{40}$/);assert.match(f.sha256,/^[a-f0-9]{64}$/);}
 for(const f of m.addedFiles){assert.match(f.gitBlob,/^[a-f0-9]{40}$/);assert.match(f.sha256,/^[a-f0-9]{64}$/);}
 if(m===cached)validated.add(m);return m;
}
export function previewFastGateParentBytes(path,bytes,m=manifest()){
 validate(m);bytes=Buffer.from(bytes);const f=m.files.find(f=>f.path===path);if(!f)return bytes;
 const before=Buffer.from(f.beforeText);if(before.equals(bytes))return before;
 assert.equal(gitBlob(bytes),f.gitBlob,path+' previewFastGate live drift');assert.equal(sha256(bytes),f.sha256,path+' previewFastGate live SHA256 drift');return before;
}
export function readBeforePreviewFastGate(file,options){
 const absolute=file instanceof URL?fileURLToPath(file):resolve(String(file)),path=relative(root,absolute).split(sep).join('/');
 if(!path||path==='..'||path.startsWith('../')||isAbsolute(path))return actual(file,options);
 const encoding=typeof options==='string'?options:options?.encoding;
 const bytes=actual(file,typeof options==='object'&&options?{...options,encoding:null}:undefined);
 const before=baseline.modifiedPaths.includes(path)?previewFastGateParentBytes(path,bytes):bytes;return encoding?before.toString(encoding):before;
}
export function inventoryBeforePreviewFastGate(paths,{read=p=>actual(new URL('../../'+p,import.meta.url)),runtimeOnly=false}={}){
 assert.equal(new Set(paths).size,paths.length,'duplicate previewFastGate inventory');const m=validate(manifest());
 if(!paths.some(p=>m.addedPaths.includes(p)))return paths;
 const runtime=p=>/^(public|worker|src|config)\//.test(p),onlyRuntime=runtimeOnly||paths.every(runtime);
 const additions=m.addedPaths.filter(p=>!onlyRuntime||runtime(p));
 for(const p of additions)assert.equal(paths.filter(x=>x===p).length,1,p+' previewFastGate addition must appear once');
 for(const f of [...m.files,...m.addedFiles].filter(f=>!onlyRuntime||runtime(f.path))){const bytes=read(f.path);assert.equal(gitBlob(bytes),f.gitBlob,f.path+' previewFastGate inventory live drift');assert.equal(sha256(bytes),f.sha256,f.path+' previewFastGate inventory SHA256 drift');}
 return paths.filter(p=>!additions.includes(p));
}
export function assertCompleteInventory(paths,{read=p=>actual(new URL('../../'+p,import.meta.url))}={}){
 assert.deepEqual([...paths].sort(),[...baseline.files.map(f=>f.path),...baseline.addedPaths].sort(),'complete previewFastGate inventory');
 assert.deepEqual(inventoryBeforePreviewFastGate(paths,{read}).sort(),baseline.files.map(f=>f.path).sort());
 for(const f of baseline.files)assert.equal(gitBlob(previewFastGateParentBytes(f.path,read(f.path))),f.gitBlob,f.path+' exact immutable parent');
