  await writeFile(join(dir,'docs/pinball/MANIFEST.json'),'{broken json');
  assert.throws(()=>isolated.manifest(),SyntaxError);assert.throws(()=>isolated.manifest(),SyntaxError);
 }finally{await rm(dir,{recursive:true,force:true});}
});

