test('gate rejects unknown missing duplicate and changed source',()=>{const paths=inventory();assert.throws(()=>b.assertCompleteInventory([...paths,'unknown.js']));assert.throws(()=>b.assertCompleteInventory([...paths,paths[0]]));for(const p of b.baseline.addedPaths)assert.throws(()=>b.assertCompleteInventory(paths.filter(x=>x!==p)));for(const f of [...b.manifest().files,...b.manifest().addedFiles])assert.throws(()=>b.assertCompleteInventory(paths,{read:p=>p===f.path?Buffer.from('drift'):read(p)}));});
test('gate rejects forged parent preimage and admission',()=>{const m=b.manifest();for(const f of m.files){const bad=structuredClone(m),x=bad.files.find(x=>x.path===f.path);x.beforeText+='forged';x.beforeGitBlob=b.gitBlob(Buffer.from(x.beforeText));x.beforeSha256=b.sha256(Buffer.from(x.beforeText));assert.throws(()=>b.validate(bad));}for(const key of ['baseCommit','baseTree']){const bad=structuredClone(m);bad[key]='0'.repeat(40);assert.throws(()=>b.validate(bad));}const bad=structuredClone(m);bad.addedPaths.push('unknown');assert.throws(()=>b.validate(bad));assert.equal(Object.isFrozen(m.files[0]),true);assert.throws(()=>{m.files[0].beforeText+='x';},TypeError);});
test('gate cache rechecks disk mutations and malformed JSON',async()=>{const {mkdtemp,mkdir,writeFile,rm}=await import('node:fs/promises');const {tmpdir}=await import('node:os');const {join}=await import('node:path');const {pathToFileURL}=await import('node:url');const dir=await mkdtemp(join(tmpdir(),'gate-proof-'));try{await mkdir(join(dir,'tests/helpers'),{recursive:true});await mkdir(join(dir,'docs/preview-fast-gate'),{recursive:true});for(const p of ['tests/helpers/preview-fast-gate-provenance.mjs','docs/preview-fast-gate/BASELINE.json','docs/preview-fast-gate/MANIFEST.json'])await writeFile(join(dir,p),read(p));const isolated=await import(pathToFileURL(join(dir,'tests/helpers/preview-fast-gate-provenance.mjs')));isolated.validate(isolated.manifest());const m=structuredClone(isolated.manifest());m.files[0].beforeText+='x';await writeFile(join(dir,'docs/preview-fast-gate/MANIFEST.json'),JSON.stringify(m));assert.throws(()=>isolated.validate(isolated.manifest()));await writeFile(join(dir,'docs/preview-fast-gate/MANIFEST.json'),'{');assert.throws(()=>isolated.manifest(),SyntaxError);assert.throws(()=>isolated.manifest(),SyntaxError);}finally{await rm(dir,{recursive:true,force:true});}});

